function sortNumbers(nums) {
  return [...nums].sort((a, b) => a - b);   // without (a, b) => a - b, JS compares as text: [10, 9, 1] -> [1, 10, 9]
}

int[] sortNumbers(int[] nums) {
    int[] copy = nums.clone();
    Arrays.sort(copy);                    // sorts in place; for objects use a Comparator
    return copy;
}

vector<int> sortNumbers(vector<int> nums) {
    sort(nums.begin(), nums.end());       // pass a third argument to compare differently
    return nums;
}
